def settle(grid):
 R,C=len(grid),len(grid[0]); seen=set(); comps=[]
 for r in range(R):
  for c in range(C):
   if grid[r][c] and (r,c) not in seen:
    col=grid[r][c]; st=[(r,c)];seen.add((r,c));pts=[]
    while st:
     x,y=st.pop();pts.append((x,y))
     for q in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
      if 0<=q[0]<R and 0<=q[1]<C and q not in seen and grid[q[0]][q[1]]==col:
       seen.add(q);st.append(q)
    comps.append({'color':col,'pts':pts,'shift':0})
 def occupied_except(i):
  return {(r,c+x['shift']) for j,x in enumerate(comps) if j!=i for r,c in x['pts']}
 while True:
  changed=False
  # move rightmost to leftmost, as far as possible
  order=sorted(range(len(comps)),key=lambda i:max(c+comps[i]['shift'] for r,c in comps[i]['pts']),reverse=True)
  for i in order:
   x=comps[i]
   while True:
    nxt={(r,c+x['shift']+1) for r,c in x['pts']}
    if max(c+x['shift'] for r,c in x['pts'])+1>=C or nxt & occupied_except(i): break
    x['shift']+=1;changed=True
  if not changed: break
 out=[[0]*C for _ in range(R)]
 for x in comps:
  for r,c in x['pts']: out[r][c+x['shift']]=x['color']
 return out,[(x['color'],x['shift'],x['pts']) for x in comps]
